(function () {
  function registerFor(generatorObj, mode) {
    if (!generatorObj || !generatorObj.forBlock) {
      return;
    }

    var isArduino = mode === 'arduino';
    var emit = function (pythonCall, commentText) {
      if (isArduino) {
        return '// ' + commentText + '\n';
      }
      return pythonCall;
    };

    var getNumberField = function (block, key, fallback) {
      var raw = block && typeof block.getFieldValue === 'function' ? block.getFieldValue(key) : null;
      var n = Number(raw);
      if (!Number.isFinite(n)) {
        return fallback;
      }
      return n;
    };

    var getTextField = function (block, key, fallback) {
      var raw = block && typeof block.getFieldValue === 'function' ? block.getFieldValue(key) : null;
      var text = String(raw == null ? '' : raw).trim();
      if (!text) {
        return fallback;
      }
      return text;
    };

    var atomicOrder = Number(
      generatorObj.ORDER_ATOMIC != null
        ? generatorObj.ORDER_ATOMIC
        : (generatorObj.ORDER_FUNCTION_CALL != null ? generatorObj.ORDER_FUNCTION_CALL : 0)
    );

    var escapePyString = function (value) {
      return String(value || '')
        .replace(/\\/g, '\\\\')
        .replace(/'/g, "\\'")
        .replace(/\r/g, '\\r')
        .replace(/\n/g, '\\n');
    };

    generatorObj.forBlock['cf_link_config'] = function () {
      var uri = getTextField(this, 'URI', 'radio://0/80/2M');
      var address = getTextField(this, 'ADDRESS', 'E7E7E7E7E7');
      var escapedUri = escapePyString(uri);
      var escapedAddress = escapePyString(address);
      return emit("cf_set_link('" + escapedUri + "', '" + escapedAddress + "');\n", "cf_set_link('" + escapedUri + "', '" + escapedAddress + "')");
    };

    generatorObj.forBlock['cf_test_link'] = function () {
      return emit('cf_test_link();\n', 'cf_test_link()');
    };

    generatorObj.forBlock['cf_detect_flow_v2'] = function () {
      return emit('cf_detect_flow_v2();\n', 'cf_detect_flow_v2()');
    };

    generatorObj.forBlock['cf_detect_multiranger'] = function () {
      return emit('cf_detect_multiranger();\n', 'cf_detect_multiranger()');
    };

    generatorObj.forBlock['cf_mr_get_distance'] = function () {
      var dir = getTextField(this, 'DIR', 'front').toLowerCase();
      var expr = "cf_mr_get_distance('" + dir + "')";
      if (isArduino) {
        return ['0', atomicOrder];
      }
      return [expr, atomicOrder];
    };

    generatorObj.forBlock['cf_mr_has_obstacle'] = function () {
      var dir = getTextField(this, 'DIR', 'front').toLowerCase();
      var threshold = getNumberField(this, 'THRESHOLD', 0.3);
      var expr = "cf_mr_has_obstacle('" + dir + "', " + threshold + ")";
      if (isArduino) {
        return ['false', atomicOrder];
      }
      return [expr, atomicOrder];
    };

    generatorObj.forBlock['cf_mr_log_distance'] = function () {
      var dir = getTextField(this, 'DIR', 'front').toLowerCase();
      return emit("cf_mr_log_distance('" + dir + "');\n", "cf_mr_log_distance('" + dir + "')");
    };

    generatorObj.forBlock['cf_mr_log_all_distances'] = function () {
      return emit('cf_mr_log_all_distances();\n', 'cf_mr_log_all_distances()');
    };

    generatorObj.forBlock['cf_detect_led_ring'] = function () {
      return emit('cf_detect_led_ring();\n', 'cf_detect_led_ring()');
    };

    generatorObj.forBlock['cf_led_ring_set_color'] = function () {
      var r = Math.max(0, Math.min(255, Math.round(getNumberField(this, 'R', 255))));
      var g = Math.max(0, Math.min(255, Math.round(getNumberField(this, 'G', 0))));
      var b = Math.max(0, Math.min(255, Math.round(getNumberField(this, 'B', 0))));
      return emit('cf_led_ring_set_color(' + r + ', ' + g + ', ' + b + ');\n', 'cf_led_ring_set_color(' + r + ', ' + g + ', ' + b + ')');
    };

    generatorObj.forBlock['cf_led_ring_set_effect'] = function () {
      var effect = Math.round(getNumberField(this, 'EFFECT', 0));
      return emit('cf_led_ring_set_effect(' + effect + ');\n', 'cf_led_ring_set_effect(' + effect + ')');
    };

    generatorObj.forBlock['cf_led_ring_off'] = function () {
      return emit('cf_led_ring_off();\n', 'cf_led_ring_off()');
    };

    generatorObj.forBlock['cf_detect_buzzer'] = function () {
      return emit('cf_detect_buzzer();\n', 'cf_detect_buzzer()');
    };

    generatorObj.forBlock['cf_buzzer_beep'] = function () {
      var duration = Math.max(20, Math.min(2000, Math.round(getNumberField(this, 'DURATION', 120))));
      var times = Math.max(1, Math.min(20, Math.round(getNumberField(this, 'TIMES', 1))));
      return emit('cf_buzzer_beep(' + duration + ', ' + times + ');\n', 'cf_buzzer_beep(' + duration + ', ' + times + ')');
    };

    generatorObj.forBlock['cf_takeoff'] = function () {
      return emit('cf_takeoff();\n', 'cf_takeoff()');
    };

    generatorObj.forBlock['cf_land'] = function () {
      return emit('cf_land();\n', 'cf_land()');
    };

    generatorObj.forBlock['cf_motor_ramp_test'] = function () {
      var start = Math.max(1000, Math.min(60000, Math.round(getNumberField(this, 'START', 20000))));
      var end = Math.max(1000, Math.min(60000, Math.round(getNumberField(this, 'END', 25000))));
      var step = Math.max(50, Math.min(5000, Math.round(getNumberField(this, 'STEP', 500))));
      var intervalMs = Math.max(20, Math.min(500, Math.round(getNumberField(this, 'INTERVAL_MS', 100))));
      var settleSecs = Math.max(0.2, Math.min(5, getNumberField(this, 'SETTLE_SECS', 0.8)));
      return emit('cf_motor_ramp_test(' + start + ', ' + end + ', ' + step + ', ' + intervalMs + ', ' + settleSecs + ');\n', 'cf_motor_ramp_test(' + start + ', ' + end + ', ' + step + ', ' + intervalMs + ', ' + settleSecs + ')');
    };

    generatorObj.forBlock['cf_move_forward'] = function () {
      var dist = getNumberField(this, 'DIST', 0.5);
      return emit("cf_move('forward', " + dist + ");\n", "cf_move('forward', " + dist + ")");
    };

    generatorObj.forBlock['cf_move_back'] = function () {
      var dist = getNumberField(this, 'DIST', 0.5);
      return emit("cf_move('back', " + dist + ");\n", "cf_move('back', " + dist + ")");
    };

    generatorObj.forBlock['cf_move_left'] = function () {
      var dist = getNumberField(this, 'DIST', 0.3);
      return emit("cf_move('left', " + dist + ");\n", "cf_move('left', " + dist + ")");
    };

    generatorObj.forBlock['cf_move_right'] = function () {
      var dist = getNumberField(this, 'DIST', 0.3);
      return emit("cf_move('right', " + dist + ");\n", "cf_move('right', " + dist + ")");
    };

    generatorObj.forBlock['cf_move_up'] = function () {
      var dist = getNumberField(this, 'DIST', 0.2);
      return emit("cf_move('up', " + dist + ");\n", "cf_move('up', " + dist + ")");
    };

    generatorObj.forBlock['cf_move_down'] = function () {
      var dist = getNumberField(this, 'DIST', 0.2);
      return emit("cf_move('down', " + dist + ");\n", "cf_move('down', " + dist + ")");
    };

    generatorObj.forBlock['cf_delay'] = function () {
      var secs = getNumberField(this, 'SECS', 1);
      return emit("cf_delay(" + secs + ");\n", "cf_delay(" + secs + ")");
    };

    generatorObj.forBlock['cf_print'] = function () {
      var value = "''";
      if (typeof generatorObj.valueToCode === 'function') {
        value = generatorObj.valueToCode(this, 'VALUE', 0) || "''";
      }
      return emit("cf_print(" + value + ");\n", "cf_print(" + value + ")");
    };

    generatorObj.forBlock['cf_print_text'] = function () {
      var text = this && typeof this.getFieldValue === 'function' ? this.getFieldValue('TEXT') : '';
      var escaped = String(text || '')
        .replace(/\\/g, '\\\\')
        .replace(/'/g, "\\'")
        .replace(/\r/g, '\\r')
        .replace(/\n/g, '\\n');
      var value = "'" + escaped + "'";
      return emit("cf_print(" + value + ");\n", "cf_print(" + value + ")");
    };
  }

  registerFor(window.Arduino, 'arduino');
  registerFor(window.MPY || window.MicropPython, 'python');
  registerFor((window.Blockly && window.Blockly.JavaScript) || null, 'javascript');
})();
